const folderId = '1bCogRhQvDgHLzrGPLd9YKl8IjOp1_8h7';
const files = $input.all()
  .map(item => item.json)
  .filter(file => file && file.id)
  .filter(file => String(file.name ?? '').toLowerCase().endsWith('.json') || file.mimeType === 'application/json');

if (files.length === 0) {
  throw new Error('Im Ordner Neues Ticket wurde keine JSON-Ticketdatei gefunden.');
}

const timestamp = file => {
  const value = file.modifiedTime ?? file.createdTime;
  if (!value) return null;
  const parsed = Date.parse(value);
  return Number.isFinite(parsed) ? parsed : null;
};

const withoutTimestamp = files.filter(file => timestamp(file) === null);
if (withoutTimestamp.length > 0) {
  throw new Error('Google Drive liefert für ' + withoutTimestamp.length + ' JSON-Datei(en) keinen modifiedTime/createdTime-Wert. Im Node Google Drive – Tickets suchen muss Options → Fields = All eingestellt sein. Auswahl abgebrochen, damit nicht das falsche Ticket verarbeitet wird.');
}

files.sort((a, b) => timestamp(b) - timestamp(a));
const latest = files[0];

return [{ json: {
  ...latest,
  sourceFileId: latest.id,
  sourceFolderId: folderId,
  selectedAsNewest: true,
  selectedTimestamp: latest.modifiedTime ?? latest.createdTime,
  jsonTicketCount: files.length
} }];

const rawTicket = $input.first().json;
const ticket = rawTicket && rawTicket.data && typeof rawTicket.data === 'object' && !Array.isArray(rawTicket.data)
  ? rawTicket.data
  : rawTicket;
const serialized = JSON.stringify(ticket);
if (!ticket || typeof ticket !== 'object' || Array.isArray(ticket)) throw new Error('Das Ticket muss ein JSON-Objekt sein.');
if (serialized.length > 250000) throw new Error('Das Ticket ist für diesen MVP zu groß (maximal 250.000 Zeichen).');
const ticketId = String(ticket.ticketId ?? ticket.ticket_id ?? ticket.lieferung_id ?? ticket.id ?? 'UNBEKANNT');
return [{ json: { ticketId, ticket, ticketText: JSON.stringify(ticket, null, 2) } }];

