let specification = $json.output ?? $json;
if (typeof specification === 'string') {
  try { specification = JSON.parse(specification); } catch (error) { throw new Error('Ticketanalyse ist kein gültiges JSON: ' + error.message); }
}
const prepared = $('Ticket vorbereiten').first().json;
if (!specification || typeof specification !== 'object') throw new Error('Keine strukturierte Ticketspezifikation erhalten.');
return [{ json: {
  ticketId: prepared.ticketId,
  specification,
  originalTicket: prepared.ticket,
  ticketText: prepared.ticketText
} }];

const input = $input.first().json;
const rawCandidate = input.text ?? input.output ?? input.response ?? input.rawOutput ?? input;
let raw = typeof rawCandidate === 'string' ? rawCandidate.trim() : JSON.stringify(rawCandidate);
const fence = String.fromCharCode(96).repeat(3);
if (raw.startsWith(fence)) raw = raw.slice(3).replace(/^json\s*/i, '');
if (raw.endsWith(fence)) raw = raw.slice(0, -3).trim();
const firstBrace = raw.indexOf('{');
const lastBrace = raw.lastIndexOf('}');
if (firstBrace >= 0 && lastBrace > firstBrace) raw = raw.slice(firstBrace, lastBrace + 1);

const errors = [];
let workflow = null;
try { workflow = JSON.parse(raw); } catch (error) { errors.push('Ungültiges JSON: ' + error.message); }

const allowedTypes = new Set([
  'n8n-nodes-base.manualTrigger','n8n-nodes-base.webhook','n8n-nodes-base.formTrigger','n8n-nodes-base.form',
  'n8n-nodes-base.set','n8n-nodes-base.code','n8n-nodes-base.if','n8n-nodes-base.switch',
  'n8n-nodes-base.merge','n8n-nodes-base.httpRequest','n8n-nodes-base.wait',
  'n8n-nodes-base.respondToWebhook','n8n-nodes-base.splitOut','n8n-nodes-base.splitInBatches',
  'n8n-nodes-base.noOp','n8n-nodes-base.stickyNote','n8n-nodes-base.convertToFile',
  'n8n-nodes-base.extractFromFile','n8n-nodes-base.gmail','n8n-nodes-base.emailSend',
  'n8n-nodes-base.postgres','n8n-nodes-base.supabase',
  '@n8n/n8n-nodes-langchain.chainLlm','@n8n/n8n-nodes-langchain.lmChatAnthropic',
  '@n8n/n8n-nodes-langchain.outputParserStructured'
]);

if (workflow && typeof workflow === 'object' && !Array.isArray(workflow)) {
  if (typeof workflow.name !== 'string' || !workflow.name.trim()) errors.push('Workflow-Name fehlt.');
  if (!Array.isArray(workflow.nodes) || workflow.nodes.length === 0) errors.push('nodes fehlt oder ist leer.');
  if (!workflow.connections || typeof workflow.connections !== 'object' || Array.isArray(workflow.connections)) errors.push('connections fehlt oder ist ungültig.');

  if (Array.isArray(workflow.nodes)) {
    const names = new Set();
    const ids = new Set();
    for (const [index, node] of workflow.nodes.entries()) {
      if (!node || typeof node !== 'object') { errors.push('Node ' + index + ' ist ungültig.'); continue; }
      if (!node.name) errors.push('Node ' + index + ' hat keinen Namen.');
      else if (names.has(node.name)) errors.push('Doppelter Node-Name: ' + node.name);
      else names.add(node.name);
      if (!node.id) errors.push('Node ' + (node.name ?? index) + ' hat keine ID.');
      else if (ids.has(node.id)) errors.push('Doppelte Node-ID: ' + node.id);
      else ids.add(node.id);
      if (!allowedTypes.has(node.type)) errors.push('Nicht erlaubter oder unbekannter Nodetyp: ' + node.type);
      if (node.credentials && Object.keys(node.credentials).length > 0) errors.push('Credentials eingebettet in Node: ' + node.name);
      if (!Array.isArray(node.position) || node.position.length !== 2) errors.push('Ungültige Position bei Node: ' + node.name);
      if (!node.parameters || typeof node.parameters !== 'object') errors.push('parameters fehlt bei Node: ' + node.name);
      if (node.type === 'n8n-nodes-base.set' && Number(node.typeVersion) >= 3) {
        const setParameters = node.parameters && typeof node.parameters === 'object' ? node.parameters : {};
        if (Object.prototype.hasOwnProperty.call(setParameters, 'fields')) errors.push('Set-Node ab Version 3 verwendet das veraltete Feld parameters.fields: ' + node.name);
        const setMode = setParameters.mode ?? 'manual';
        if (setMode === 'manual') {
          const assignments = setParameters.assignments && setParameters.assignments.assignments;
          if (!Array.isArray(assignments) || assignments.length === 0) {
            errors.push('Set-Node ab Version 3 benötigt im Modus manual parameters.assignments.assignments: ' + node.name);
          } else {
            for (const [assignmentIndex, assignment] of assignments.entries()) {
              const label = node.name + ' Zuweisung ' + assignmentIndex;
              if (!assignment || typeof assignment !== 'object') { errors.push('Ungültige Set-Zuweisung: ' + label); continue; }
              if (typeof assignment.id !== 'string' || !assignment.id.trim()) errors.push('Set-Zuweisung ohne id: ' + label);
              if (typeof assignment.name !== 'string' || !assignment.name.trim()) errors.push('Set-Zuweisung ohne name: ' + label);
              if (!Object.prototype.hasOwnProperty.call(assignment, 'value')) errors.push('Set-Zuweisung ohne value: ' + label);
              if (typeof assignment.type !== 'string' || !assignment.type.trim()) errors.push('Set-Zuweisung ohne type: ' + label);
            }
          }
        } else if (setMode === 'raw' && (typeof setParameters.jsonOutput !== 'string' || !setParameters.jsonOutput.trim())) {
          errors.push('Set-Node im Modus raw benötigt jsonOutput: ' + node.name);
        }
      }
      if (node.type === '@n8n/n8n-nodes-langchain.chainLlm') {
        if (node.parameters.promptType !== 'define') errors.push('LLM-Chain muss promptType=define verwenden: ' + node.name);
        if (typeof node.parameters.text !== 'string' || !node.parameters.text.trim()) errors.push('LLM-Chain besitzt keinen ausführbaren Text-Prompt: ' + node.name);
        const promptText = node.parameters.text;
        if (typeof promptText === 'string' && promptText.trim() && !(promptText.includes('{{') && promptText.includes('$json') && promptText.includes('}}'))) errors.push('LLM-Chain-Prompt verwendet keine dynamischen Eingangsdaten ($json): ' + node.name);
        if (Object.prototype.hasOwnProperty.call(node.parameters, 'prompt')) errors.push('LLM-Chain verwendet das ungültige Feld parameters.prompt statt parameters.text: ' + node.name);
      }
      if (node.type === '@n8n/n8n-nodes-langchain.lmChatAnthropic') {
        if (Number(node.typeVersion) >= 1.3 && (!node.parameters.model || typeof node.parameters.model !== 'object' || typeof node.parameters.model.value !== 'string' || !node.parameters.model.value.trim())) {
          errors.push('Anthropic-Node benötigt ab Version 1.3 ein model.value Resource-Locator-Objekt: ' + node.name);
        }
        if (node.parameters.options && Object.prototype.hasOwnProperty.call(node.parameters.options, 'maxTokens')) {
          errors.push('Anthropic-Node verwendet options.maxTokens statt options.maxTokensToSample: ' + node.name);
        }
      }
    }

    if (workflow.connections && typeof workflow.connections === 'object') {
      const inspectLinks = (value, sourceName, path = '') => {
        if (Array.isArray(value)) {
          for (const item of value) inspectLinks(item, sourceName, path);
        } else if (value && typeof value === 'object') {
          if (typeof value.node === 'string' && !names.has(value.node)) {
            errors.push('Connection von ' + sourceName + ' zeigt auf unbekannten Node: ' + value.node);
          }
          for (const [key, child] of Object.entries(value)) inspectLinks(child, sourceName, path + '/' + key);
        }
      };
      for (const [sourceName, channels] of Object.entries(workflow.connections)) {
        if (!names.has(sourceName)) errors.push('Connection-Quelle existiert nicht: ' + sourceName);
        inspectLinks(channels, sourceName);
      }
    }
  }

  if (Array.isArray(workflow.nodes) && workflow.connections && typeof workflow.connections === 'object') {
    const allConnectionGroups = Object.values(workflow.connections);
    for (const chain of workflow.nodes.filter(node => node.type === '@n8n/n8n-nodes-langchain.chainLlm')) {
      const hasModel = allConnectionGroups.some(channels =>
        Array.isArray(channels.ai_languageModel) &&
        channels.ai_languageModel.flat(2).some(link => link && link.node === chain.name && link.type === 'ai_languageModel')
      );
      const hasMainInput = allConnectionGroups.some(channels =>
        Array.isArray(channels.main) &&
        channels.main.flat(2).some(link => link && link.node === chain.name && link.type === 'main')
      );
      if (!hasModel) errors.push('LLM-Chain hat keine ai_languageModel-Verbindung: ' + chain.name);
      if (!hasMainInput) errors.push('LLM-Chain hat keinen eingehenden main-Datenpfad: ' + chain.name);
    }
  }

  if (workflow.connections && typeof workflow.connections === 'object') {
    for (const [sourceName, channels] of Object.entries(workflow.connections)) {
      if (/AWAITING_HUMAN_APPROVAL/i.test(sourceName)) {
        const outgoingMain = channels && Array.isArray(channels.main)
          ? channels.main.flat(2).filter(link => link && typeof link.node === 'string')
          : [];
        if (outgoingMain.length > 0) errors.push('AWAITING_HUMAN_APPROVAL darf im MVP keine ausgehende main-Verbindung besitzen: ' + sourceName);
      }
    }
  }


  if (Array.isArray(workflow.nodes) && workflow.connections && typeof workflow.connections === 'object') {
    const nodeByName = new Map(workflow.nodes.map(node => [node.name, node]));
    const outgoingMain = sourceName => {
      const channels = workflow.connections[sourceName];
      return channels && Array.isArray(channels.main)
        ? channels.main.flat(2).filter(link => link && typeof link.node === 'string')
        : [];
    };
    const incomingMain = new Map();
    for (const [sourceName, channels] of Object.entries(workflow.connections)) {
      if (!channels || !Array.isArray(channels.main)) continue;
      for (const outputs of channels.main) {
        for (const link of Array.isArray(outputs) ? outputs : []) {
          if (!link || typeof link.node !== 'string') continue;
          if (!incomingMain.has(link.node)) incomingMain.set(link.node, []);
          incomingMain.get(link.node).push({ sourceName, targetInput: Number(link.index ?? 0) });
        }
      }
    }

    for (const targetNode of workflow.nodes) {
      if (targetNode.type === 'n8n-nodes-base.merge') {
        const incoming = incomingMain.get(targetNode.name) ?? [];
        const distinctInputs = new Set(incoming.map(link => link.targetInput));
        if (Number(targetNode.typeVersion) >= 3 && targetNode.parameters?.mode === 'passThrough') {
          errors.push('Merge-Node ab Version 3 verwendet den veralteten Modus passThrough: ' + targetNode.name);
        }
        if (incoming.length > 0 && distinctInputs.size < 2) {
          errors.push('Merge-Node erhält alle Verbindungen nur auf demselben Eingang und wartet auf einen fehlenden Eingang: ' + targetNode.name);
        }
      }

      if (targetNode.type === 'n8n-nodes-base.set' && Number(targetNode.typeVersion) >= 3) {
        if (outgoingMain(targetNode.name).length > 0 && targetNode.parameters?.includeOtherFields !== true) {
          errors.push('Set-Node innerhalb der Datenkette muss includeOtherFields=true verwenden, damit Vorgangsdaten erhalten bleiben: ' + targetNode.name);
        }
      }

      if (targetNode.type === '@n8n/n8n-nodes-langchain.chainLlm') {
        for (const link of outgoingMain(targetNode.name)) {
          const nextNode = nodeByName.get(link.node);
          if (nextNode?.type !== 'n8n-nodes-base.code') continue;
          const code = String(nextNode.parameters?.jsCode ?? '');
          if (!/\$\s*\(\s*['"][^'"]+['"]\s*\)/.test(code)) {
            errors.push('Code-Node nach LLM stellt die vorherigen Vorgangsdaten nicht über einen benannten Node-Bezug wieder her: ' + nextNode.name);
          }
        }
      }
    }
  }

  const sourceTicket = $('Spezifikation zusammenführen').first().json;
  const sourceOriginal = sourceTicket?.originalTicket ?? {};
  const sourceIds = [sourceTicket?.ticketId, sourceOriginal.lieferung_id, sourceOriginal.ticketId, sourceOriginal.ticket_id, sourceOriginal.id, sourceOriginal.projekt_kurzname, sourceOriginal.useCase, sourceOriginal.use_case].filter(Boolean).map(value => String(value).toLowerCase()).join(' | ');
  const isUc1 = /(^|[^a-z0-9])uc\s*[-_]?\s*1([^a-z0-9]|$)|reisebuchung/.test(sourceIds);
  if (isUc1 && Array.isArray(workflow.nodes)) {
    const byName = new Map(workflow.nodes.map(node => [node.name, node]));
    const requiredUc1 = [
      ['Reisedaten manuell eingeben','n8n-nodes-base.formTrigger'],
      ['Reisedaten normalisieren','n8n-nodes-base.code'],['Eingaben gültig?','n8n-nodes-base.if'],
      ['Flüge suchen','n8n-nodes-base.httpRequest'],['Flugdaten zusammenführen','n8n-nodes-base.merge'],
      ['Hotels suchen','n8n-nodes-base.httpRequest'],['Hoteldaten zusammenführen','n8n-nodes-base.merge'],
      ['Leihwagen suchen','n8n-nodes-base.httpRequest'],['Leihwagendaten zusammenführen','n8n-nodes-base.merge'],
      ['Angebot erstellen','n8n-nodes-base.code'],['Angebote vorhanden?','n8n-nodes-base.if'],
      ['Budget überschritten?','n8n-nodes-base.if'],['Budgetfreigabe einholen','n8n-nodes-base.form'],
      ['Angebotslink senden','n8n-nodes-base.code'],['Kundenbestätigung erfassen','n8n-nodes-base.form'],
      ['Kunde bestätigt?','n8n-nodes-base.if'],['Zahlungslink erstellen','n8n-nodes-base.code'],
      ['Zahlung erfassen','n8n-nodes-base.form'],['Zahlung erfolgreich?','n8n-nodes-base.if'],
      ['Zahlung erneut anfordern','n8n-nodes-base.set'],['Gewählte Leistungen buchen','n8n-nodes-base.code'],
      ['Buchungsbestätigung senden','n8n-nodes-base.set']
    ];
    for (const [name,type] of requiredUc1) {
      const found = byName.get(name);
      if (!found) errors.push('UC1-Pflichtschritt fehlt: ' + name);
      else if (found.type !== type) errors.push('UC1-Pflichtschritt hat falschen Nodetyp: ' + name);
    }
    if (byName.has('Was wird benötigt?')) errors.push('UC1 darf keine vorgeschaltete Leistungsauswahl enthalten.');
    const details = byName.get('Reisedaten manuell eingeben');
    const fields = details?.parameters?.formFields?.values;
    const fieldText = Array.isArray(fields) ? fields.map(f => String(f.fieldLabel ?? f.fieldName ?? '').toLowerCase()).join(' | ') : '';
    for (const label of ['reisebeginn','reiseende','urlaubsort','budget','personen','flughafen','e-mail']) {
      if (!fieldText.includes(label)) errors.push('UC1-Formularfeld fehlt: ' + label);
    }
    const apiChecks = [
      ['Flüge suchen','/api/flights/search',['origin','destination','departureDate','numberOfAdults','numberOfChildren','numberOfInfants']],
      ['Hotels suchen','/api/hotels/search',['destination','numberOfAdults']],
      ['Leihwagen suchen','/api/cars/search',['location']]
    ];
    for (const [name,path,params] of apiChecks) {
      const n = byName.get(name); if (!n) continue;
      if (typeof n.parameters?.url !== 'string' || !n.parameters.url.includes(path)) errors.push('UC1-API-Endpunkt falsch: ' + name);
      const query = n.parameters?.queryParameters?.parameters;
      const keys = Array.isArray(query) ? query.map(p => p.name) : [];
      for (const param of params) if (!keys.includes(param)) errors.push('UC1-API-Parameter fehlt bei ' + name + ': ' + param);
    }
    const requiredEdges = [
      ['Reisedaten manuell eingeben','Reisedaten normalisieren'],['Reisedaten normalisieren','Eingaben gültig?'],
      ['Flüge suchen','Flugdaten zusammenführen'],['Flugdaten zusammenführen','Hotels suchen'],
      ['Hotels suchen','Hoteldaten zusammenführen'],['Hoteldaten zusammenführen','Leihwagen suchen'],
      ['Leihwagen suchen','Leihwagendaten zusammenführen'],['Leihwagendaten zusammenführen','Angebot erstellen'],
      ['Angebot erstellen','Angebote vorhanden?'],['Angebotslink senden','Kundenbestätigung erfassen'],
      ['Kundenbestätigung erfassen','Kunde bestätigt?'],['Zahlungslink erstellen','Zahlung erfassen'],
      ['Zahlung erfassen','Zahlung erfolgreich?'],['Gewählte Leistungen buchen','Buchungsbestätigung senden']
    ];
    const targets = source => {
      const c = workflow.connections?.[source];
      return c?.main ? c.main.flat(2).filter(Boolean).map(x => x.node) : [];
    };
    for (const [source,target] of requiredEdges) if (!targets(source).includes(target)) errors.push('UC1-Verbindung fehlt: ' + source + ' → ' + target);
    const budgetTargets = targets('Budget überschritten?');
    if (!budgetTargets.includes('Budgetfreigabe einholen') || !budgetTargets.includes('Angebotslink senden')) errors.push('UC1-Budgetentscheidung besitzt nicht beide Pfade.');
    const paymentTargets = targets('Zahlung erfolgreich?');
    if (!paymentTargets.includes('Gewählte Leistungen buchen') || !paymentTargets.includes('Zahlung erneut anfordern')) errors.push('UC1-Zahlungsentscheidung besitzt nicht beide Pfade.');
  }

  workflow.active = false;
  workflow.settings = workflow.settings && typeof workflow.settings === 'object' ? workflow.settings : {};
  workflow.settings.executionOrder = workflow.settings.executionOrder || 'v1';
  delete workflow.id;
  delete workflow.versionId;
  delete workflow.shared;
}

return [{ json: {
  valid: errors.length === 0,
  validationErrors: errors,
  rawOutput: raw,
  workflow
} }];

